<?php
declare(strict_types=1);
/** Verify faculty-owned rosters and profile employment types without data writes. */
if(PHP_SAPI!=='cli')exit;
ob_start();require dirname(__DIR__).'/config/database.php';require dirname(__DIR__).'/includes/faculty-rosters.php';require __DIR__.'/rehearsal-receipts.php';
require __DIR__.'/release-preview-target.php';
$base=getenv('NORTHBRIDGE_HTTP_BASE')?:'http://127.0.0.1:8003/';test_release_preview_target($database,$base);
$checks=0;$sessions=[];$check=static function(bool$ok,string$message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;};
$fingerprint=static function()use($pdo):array{$out=[];foreach($pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as$t)$out[$t]=$pdo->query("CHECKSUM TABLE `$t` EXTENDED")->fetch()['Checksum'];return$out;};$before=$fingerprint();
$session=static function(int$id)use($pdo,&$sessions):string{$q=$pdo->prepare('SELECT user_ID,user_Type,user_Password FROM Login WHERE user_ID=?');$q->execute([$id]);$a=$q->fetch();$sid=bin2hex(random_bytes(20));session_id($sid);session_start();$_SESSION=['user_id'=>(int)$a['user_ID'],'user_type'=>$a['user_Type'],'auth_version'=>hash('sha256',$a['user_Password'])];session_write_close();$sessions[]=$sid;return$sid;};
$request=static function(string$path,string$sid='',string$method='GET')use($base):array{$context=stream_context_create(['http'=>['method'=>$method,'header'=>$sid?"Cookie: PHPSESSID=$sid\r\n":'','follow_location'=>0,'ignore_errors'=>true,'timeout'=>30]]);$html=file_get_contents($base.$path,false,$context);$headers=http_get_last_response_headers();preg_match('/HTTP\/\S+ (\d+)/',$headers[0],$m);if($html===false||preg_match('/(?:Warning|Fatal error|Notice|Deprecated):/',$html))throw new RuntimeException('Unexpected roster page response.');return[(int)$m[1],$html,$headers];};
$expected=[];foreach($pdo->query('SELECT CRN,semester_ID,student_ID FROM Enrollment UNION SELECT CRN,semester_ID,student_ID FROM Student_History')as$r)$expected[$r['CRN']][$r['student_ID']]=true;
$sections=$pdo->query('SELECT CRN,faculty_ID,semester_ID FROM Course_Section ORDER BY CRN')->fetchAll();$assignments=0;
foreach($sections as$s){$rows=faculty_section_roster($pdo,(int)$s['faculty_ID'],(int)$s['semester_ID'],(int)$s['CRN']);$actual=array_map('intval',array_column($rows,'student_ID'));$want=array_map('intval',array_keys($expected[$s['CRN']]??[]));sort($actual);sort($want);$check($actual===$want,'Section roster must exactly match distinct enrollment/history IDs.');$assignments+=count($rows);$check(faculty_section_roster($pdo,-1,(int)$s['semester_ID'],(int)$s['CRN'])===null,'Unassigned faculty must not retrieve any roster.');}
try{
 foreach(['faculty/rosters.php','faculty/information.php']as$path)$check($request($path)[0]===302,'Anonymous requests must redirect.');
 foreach(['Student','Admin','StatStaff']as$role){$q=$pdo->prepare('SELECT user_ID FROM Login WHERE user_Type=? ORDER BY user_ID LIMIT 1');$q->execute([$role]);$sid=$session((int)$q->fetchColumn());$check($request('faculty/rosters.php',$sid)[0]===403,'Other roles must not access faculty rosters.');}
 $faculty=[];foreach(['Full-Time','Part-Time']as$type){$q=$pdo->prepare('SELECT f.faculty_ID FROM Faculty f WHERE f.faculty_Type=? AND EXISTS(SELECT 1 FROM Course_Section s WHERE s.faculty_ID=f.faculty_ID AND s.semester_ID=1) ORDER BY f.faculty_ID LIMIT 1');$q->execute([$type]);$faculty[$type]=(int)$q->fetchColumn();}
 foreach($faculty as$type=>$id){$check($id>0,'Both employment types need a real preview account.');$sid=$session($id);[$status,$profile]=$request('faculty/information.php',$sid);$check($status===200&&str_contains($profile,'<dt>Employment Type</dt><dd>'.$type.'</dd>'),'Profile must show the authenticated faculty employment type.');$check($request('faculty/information.php?faculty_id=1&user_id=1',$sid)[1]===$profile,'Profile parameters cannot select another faculty member.');
  if(in_array('--preview',$argv,true)){file_put_contents(test_receipt_path($type==='Full-Time'?'faculty-profile-full-time.json':'faculty-profile-part-time.json').'.html',str_replace('<head>','<head><base href="'.$base.'">',$profile));}
  $semesters=faculty_roster_semesters($pdo,$id);$mine=array_values(array_filter($sections,static fn($s)=>(int)$s['faculty_ID']===$id));$other=next($sections);foreach($sections as$s)if((int)$s['faculty_ID']!==$id){$other=$s;break;}
  [$status,$html,$headers]=$request('faculty/rosters.php',$sid);$check($status===200&&str_contains($html,'Fall 2026'),'Rosters must default to the current semester.');$check((bool)array_filter($headers,static fn($h)=>stripos($h,'Cache-Control:')===0&&str_contains($h,'no-store')),'Roster responses must not be cached.');
  $chosen=[];foreach($mine as$s)if(!isset($chosen[$s['semester_ID']]))$chosen[$s['semester_ID']]=$s;
  foreach($chosen as$s){$path='faculty/rosters.php?'.http_build_query(['semester_id'=>$s['semester_ID'],'crn'=>$s['CRN']]);[$status,$html]=$request($path,$sid);$check($status===200,'Assigned current, future, and historical rosters must render.');$dom=new DOMDocument();@$dom->loadHTML($html);$xp=new DOMXPath($dom);$actual=[];foreach($xp->query('//div[contains(@class,"faculty-rosters")]//tbody/tr/td[1]')as$cell)$actual[]=(int)trim($cell->textContent);$want=array_map('intval',array_keys($expected[$s['CRN']]??[]));sort($actual);sort($want);$check($actual===$want,'Rendered roster must contain exactly its own students once.');$check($xp->query('//div[contains(@class,"faculty-rosters")]//thead//th')->length===($want?6:0),'Roster columns must contain only the requested student information.');$check($request($path.'&faculty_id='.$other['faculty_ID'].'&user_id=1',$sid)[1]===$html,'URL cannot switch roster ownership.');
   if(in_array('--preview',$argv,true)&&(int)$s['semester_ID']===1&&$type==='Full-Time')file_put_contents(test_receipt_path('faculty-roster-preview.json').'.html',str_replace('<head>','<head><base href="'.$base.'">',$html));
  }
  $foreign='faculty/rosters.php?'.http_build_query(['semester_id'=>$other['semester_ID'],'crn'=>$other['CRN']]);$check(in_array($request($foreign,$sid)[0],[400,404],true),'Changing CRN must not expose another instructor roster.');
  foreach(['crn[]=1','crn=-1','crn=1%20OR%201=1','semester_id[]=1','semester_id=999999999','semester_id=0']as$query)$check($request('faculty/rosters.php?'.$query,$sid)[0]===400,'Malformed selectors must be rejected.');
  $check($request('faculty/rosters.php?semester_id=1&crn=2147483647',$sid)[0]===404,'Unknown section must not leak records.');$check($request('faculty/rosters.php',$sid,'POST')[0]===405,'Rosters must reject write requests.');
  $check($request('faculty/rosters.php?semester_id=2',$sid)[0]===200,'Next semester must render even if the faculty has no assignments.');
  [$status,$home]=$request('home.php',$sid);$check($status===200&&str_contains($home,'href="/faculty/rosters.php"'),'Home and navigation must enable Course Rosters.');
  [$status,$schedule]=$request('faculty/schedule.php',$sid);$check($status===200&&str_contains($schedule,'faculty/rosters.php?semester_id=1'),'Each assigned schedule must link to its roster.');
  $dom=new DOMDocument();@$dom->loadHTML($schedule);$xp=new DOMXPath($dom);$headers=[];foreach($xp->query('//div[contains(@class,"faculty-schedule")]//thead/tr/th')as$th)$headers[]=trim($th->textContent);$check($headers===['CRN','Course','Course Name','Section','Professor','Days','Time','Building / Room','Roster'],'Faculty schedule must match the reference order and preserve the roster action.');
 }
 $check(faculty_section_roster($pdo,(int)$sections[0]['faculty_ID'],2147483647,(int)$sections[0]['CRN'])===null,'Owned CRN must still match the requested semester.');
 $check($fingerprint()===$before,'All database table checksums must remain unchanged.');
 $summary=['status'=>'faculty-rosters-and-employment-profile-verified','database'=>$database,'checks'=>$checks,'sectionsVerified'=>count($sections),'distinctRosterAssignmentsVerified'=>$assignments,'employmentTypesVerified'=>array_keys($faculty),'facultyOwnershipVerified'=>true,'databaseWrites'=>false];$summary['runtimeSHA256']=test_runtime_hash();file_put_contents(test_receipt_path('faculty-rosters-verification.json'),json_encode($summary,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)."\n");echo json_encode($summary),"\n";
}finally{foreach($sessions as$sid){session_id($sid);session_start();$_SESSION=[];session_destroy();}ob_end_flush();}
